      "This also revokes devices and app sign-ins approved through these devices, including further approvals.": "También se revocan los dispositivos e inicios de sesión de apps aprobados desde estos dispositivos, incluidas las aprobaciones posteriores.",
      "This includes the device you are using now. You will need to sign in again.": "Esto incluye el dispositivo que estás usando. Tendrás que volver a iniciar sesión.",
      "App sign-ins are not fully listed here. Other apps approved through these devices may also lose access.": "La lista de inicios de sesión de apps está incompleta. Otras apps aprobadas desde estos dispositivos también pueden perder acceso.",
      "Review where you are signed in and which device approved each sign-in.": "Revisa dónde has iniciado sesión y qué dispositivo aprobó cada inicio.",
      "The devices that approved this device stay signed in when you sign out other devices. Revoke one individually to end its approval chain.": "Los dispositivos que aprobaron este dispositivo mantienen su sesión cuando cierras las otras sesiones. Revoca uno individualmente para finalizar su cadena de aprobación.",
      "App sign-ins and access": "Inicios de sesión y acceso de apps",
      "Ongoing app sign-ins refresh automatically. They end after 180 days without a refresh. Signing out the approving device also revokes its approved apps.": "Las sesiones continuas de apps se renuevan automáticamente. Finalizan tras 180 días sin renovación. Cerrar la sesión del dispositivo que aprobó el acceso también revoca sus apps aprobadas.",
      "Individual app-session history and last-use information are not available from this service yet. Preference grants are listed below; revoking one stops that preference access.": "Este servicio aún no ofrece el historial ni el último uso de las sesiones individuales de apps. Abajo se muestran los permisos de preferencias; revocar uno detiene ese acceso.",
      "Signed in with a code": "Sesión iniciada con un código",
      "Revoke all listed app access": "Revocar todo el acceso de apps mostrado",
      "Keep this device and its approving devices signed in?": "¿Mantener la sesión de este dispositivo y de los que lo aprobaron?",
      "Their passkeys stay registered and can sign in again.": "Sus claves de acceso siguen registradas y permiten volver a iniciar sesión.",
      "Sign out and end approved sign-ins?": "¿Cerrar sesión y finalizar los inicios de sesión aprobados?",
      "Revoke all listed app access?": "¿Revocar todo el acceso de apps mostrado?",
      "Revoke this app access?": "¿Revocar este acceso de la app?",
      "This stops new calls using these preference grants. Other grants and app connections stay active. Copies already obtained cannot be erased.": "Esto detiene las nuevas llamadas con estos permisos de preferencias. Los demás permisos y conexiones de apps siguen activos. Las copias ya obtenidas no se pueden borrar.",
      "Review and confirm what will lose access.": "Revisa y confirma qué perderá el acceso.",
      "Refresh devices before making this change.": "Actualiza los dispositivos antes de hacer este cambio.",
      "Device sessions revoked. Sign in again.": "Sesiones de dispositivos revocadas. Vuelve a iniciar sesión.",
      "Access was revoked, but the latest information could not be loaded. Refresh before making another change.": "El acceso se revocó, pero no se pudo cargar la información actualizada. Actualiza antes de hacer otro cambio.",
      "a TV or shared screen": "un televisor o una pantalla compartida",
      "a computer": "un ordenador",
      "a phone": "un teléfono",
      "This sign-in is ongoing until you disconnect it. It ends after 180 days without a refresh.": "Este inicio de sesión continúa hasta que lo desconectes. Finaliza tras 180 días sin renovación.",
      "It ends at {date}.": "Finaliza el {date}.",
      "You approved a sign-in": "Aprobaste un inicio de sesión",
      "You approved a sign-in for {subject} at {date}.": "Aprobaste un inicio de sesión para {subject} el {date}.",
      "Signing out the approving device also ends the sign-ins it approved.": "Cerrar la sesión del dispositivo que dio la aprobación también finaliza los inicios de sesión que aprobó.",
      "Not you? Review devices.": "¿No fuiste tú? Revisa los dispositivos.",

