      "Use at most 100 push rules.": "Usa como máximo 100 reglas push.",
      "Each push rule names one app, a route and optional tag and priority filters.": "Cada regla push indica una app, una entrega y filtros opcionales de etiquetas y prioridad.",
      "Only an immediate rule can bypass quiet hours.": "Solo una regla inmediata puede omitir el horario de silencio.",
