      "All owner and system tags": "Todas las etiquetas propias y del sistema",
      "App tags, system classification and your own tags have separate identities. Organization facets appear only when supplied by the service.": "Las etiquetas de apps, la clasificación del sistema y tus etiquetas tienen identidades distintas. Los filtros de organización aparecen solo cuando el servicio los proporciona.",
      "Search this page": "Buscar en esta página",
      "Search covers subjects and current plain text on this page. HTML bodies and private form results are excluded. Browse another page to search more activity.": "La búsqueda incluye asuntos y texto simple actual de esta página. Excluye cuerpos HTML y resultados privados de formularios. Cambia de página para buscar más actividad.",
