      "Historical revision. Actions are unavailable.": "Revisión histórica. Las acciones no están disponibles.",
      "Activity content": "Contenido de actividad",
      "Forms are unavailable for this activity version. App revisions and local submission results are separate.": "Los formularios no están disponibles en esta versión de actividad. Las revisiones de apps y los resultados locales son independientes.",
      "App revision history": "Historial de revisiones de la app",
