      "Why push stayed silent": "Por qué no hubo notificación push",
      "Current push decision": "Decisión push actual",
      "This explains current eligibility, not proof of delivery. Quiet hours, budgets and device consent also apply.": "Esto explica la elegibilidad actual, no demuestra la entrega. También se aplican el horario de silencio, los límites y el consentimiento del dispositivo.",
      "Activity detail": "Detalle de actividad",
      "Activity push settings": "Ajustes push de actividad",
      "Allowing activity into your feed never enables push.": "Permitir actividad en tu lista nunca activa las notificaciones push.",
      "Reload push settings": "Recargar ajustes push",
      "Push is off for every app until you choose its scope. Browser permission and an app’s urgency claim do not grant consent. Reconnecting an app requires a fresh opt-in.": "Las notificaciones push están desactivadas para cada app hasta que elijas su alcance. El permiso del navegador y la urgencia declarada por una app no dan consentimiento. Reconectar una app requiere una nueva autorización.",
      "Load your push choices": "Cargar tus opciones push",
      "Settings are scoped to this account. No permission prompt opens automatically.": "Los ajustes pertenecen a esta cuenta. No se abre automáticamente ninguna solicitud de permisos.",
      "Load push settings": "Cargar ajustes push",
      "Account push": "Notificaciones push de la cuenta",
      "Resume push": "Reanudar notificaciones push",
      "Pause all push": "Pausar todas las notificaciones push",
      "Enable activity push for this account": "Activar notificaciones push de actividad para esta cuenta",
      "Allow private activity previews on lock screens": "Permitir vistas previas privadas de actividad en pantallas bloqueadas",
      "Previews can expose app names, subjects and counts to your OS, push service and anyone viewing your screen. Both this account and each device must consent. Turning previews off cannot recall a delivered notice.": "Las vistas previas pueden revelar nombres de apps, asuntos y cantidades al sistema operativo, al servicio push y a cualquiera que vea tu pantalla. Tanto esta cuenta como cada dispositivo deben dar consentimiento. Desactivarlas no retira avisos ya entregados.",
      "Quiet hours": "Horario de silencio",
      "Use quiet hours": "Usar horario de silencio",
      "Quiet starts (hour)": "El silencio empieza (hora)",
      "Quiet ends (hour)": "El silencio termina (hora)",
      "Time zone (IANA name, optional)": "Zona horaria (nombre IANA, opcional)",
      "Fixed UTC offset in minutes": "Desfase UTC fijo en minutos",
      "A named zone follows daylight saving changes. Without one, the fixed UTC offset is used and does not adjust automatically. Equal start and end hours mean quiet all day.": "Una zona con nombre sigue los cambios de horario de verano. Sin ella se usa un desfase UTC fijo, sin ajustes automáticos. Horas de inicio y fin iguales significan silencio todo el día.",
      "Digest schedule": "Horario de resúmenes",
      "Digest frequency": "Frecuencia del resumen",
      "Hourly": "Cada hora",
      "Daily": "Diario",
      "Daily digest hour": "Hora del resumen diario",
      "Digests use the quiet-hours time zone. Read, archived, retracted and expired items are removed before sending. Empty digests disappear.": "Los resúmenes usan la zona horaria del horario de silencio. Los elementos leídos, archivados, retirados y caducados se eliminan antes del envío. Los resúmenes vacíos desaparecen.",
      "Save account push settings": "Guardar ajustes push de la cuenta",
      "Device delivery still requires separate channel and browser enrollment.": "La entrega al dispositivo sigue necesitando activar el canal y registrar el navegador por separado.",
      "Push transport is not enabled on this service. Saving policy does not prove delivery.": "El envío push no está activado en este servicio. Guardar la configuración no demuestra la entrega.",
      "Push from each app": "Notificaciones push de cada app",
      "Selected tags leave new or unknown tags feed-only. All activity explicitly includes future app tags. Changes apply to future arrivals, without replaying a backlog.": "Las etiquetas seleccionadas dejan las etiquetas nuevas o desconocidas solo en la lista. Toda la actividad incluye expresamente las etiquetas futuras de la app. Los cambios se aplican a nuevas llegadas, sin reenviar actividad anterior.",
      "Activity admission allowed": "Se permite recibir actividad",
      "Activity admission off": "Recepción de actividad desactivada",
      "Admission is managed in Connected apps. This control changes push only.": "La recepción se gestiona en Apps conectadas. Este control solo cambia las notificaciones push.",
      "Push scope": "Alcance de notificaciones push",
      "Selected app tags": "Etiquetas seleccionadas de la app",
      "All activity, including future tags": "Toda la actividad, incluidas etiquetas futuras",
