      "Default route": "Entrega predeterminada",
      "Immediate push": "Push inmediato",
      "Digest": "Resumen",
      "Save app push choice": "Guardar opción push de la app",
      "Update notifications remain subject to service support; this screen does not enable a separate update permission.": "Los avisos de actualizaciones dependen del soporte del servicio; esta pantalla no activa un permiso independiente de actualizaciones.",
      "No app connections are available. Connect an app before allowing its push.": "No hay apps conectadas disponibles. Conecta una app antes de permitir sus notificaciones push.",
      "Devices and preview consent": "Dispositivos y consentimiento de vistas previas",
      "Generic notices contain no app name, account, subject, count or tags. Device enrollment and previews are separate choices.": "Los avisos genéricos no contienen nombre de app, cuenta, asunto, cantidad ni etiquetas. El registro del dispositivo y las vistas previas se eligen por separado.",
      "Enroll this device for activity push": "Registrar este dispositivo para notificaciones push de actividad",
      "Allow private previews on this device": "Permitir vistas previas privadas en este dispositivo",
      "Anyone viewing this device’s lock screen may see private content when account previews are also enabled.": "Quien vea la pantalla bloqueada de este dispositivo puede ver contenido privado si las vistas previas de la cuenta también están activadas.",
      "Save device consent": "Guardar consentimiento del dispositivo",
      "No registered push devices. Register a browser device through the existing notification channel first.": "No hay dispositivos push registrados. Primero registra un navegador mediante el canal de notificaciones existente.",
      "Ordered push rules": "Reglas push ordenadas",
      "Hard mutes always win. Otherwise the first matching app rule chooses the route and priority. No rule can bypass missing consent, inactive items or delivery budgets.": "Los silencios explícitos siempre prevalecen. De lo contrario, la primera regla coincidente elige la entrega y prioridad. Ninguna regla evita la falta de consentimiento, los elementos inactivos ni los límites de entrega.",
      "Move rule up": "Subir regla",
      "Delete push rule": "Eliminar regla push",
      "Add push rule": "Añadir regla push",
