      "Authorize the same Google account to preserve this resource, its dedicated folder and its file mappings.": "Autoriza la misma cuenta de Google para conservar este recurso, su carpeta dedicada y las correspondencias de sus archivos.",
      "Up to 10,000 managed files and 10,000 retained versions per connection. Deleting or replacing a file here keeps older physical files in Google Drive; you manage that storage in Drive.": "Hasta 10 000 archivos administrados y 10 000 versiones retenidas por conexión. Al eliminar o reemplazar un archivo aquí se conservan los archivos físicos anteriores en Google Drive; administra ese almacenamiento en Drive.",
      "Individual uploads: 1 MiB. Up to 10,000 managed files and 10,000 retained versions. Deleted and replaced physical files remain in Google Drive.": "Cargas individuales: 1 MiB. Hasta 10 000 archivos administrados y 10 000 versiones retenidas. Los archivos físicos eliminados y reemplazados permanecen en Google Drive.",
      "Google Drive reconnected. Your existing resource and file mappings are preserved.": "Google Drive reconectado. Se conservan el recurso existente y las correspondencias de sus archivos.",
      "Refresh your resources before reconnecting Google Drive.": "Actualiza tus recursos antes de volver a conectar Google Drive.",
      "Set up Google Drive": "Configurar Google Drive",
      "Authorize with Google": "Autorizar con Google",
      "Authorize access to files created by this connection. Existing files in your Drive are not imported or listed.": "Autoriza el acceso a los archivos creados por esta conexión. No se importan ni se enumeran los archivos existentes en tu Drive.",
      "A dedicated folder holds immutable file versions. Apps maintain their own directory files; individual uploads are limited to 1 MiB.": "Una carpeta dedicada guarda versiones inmutables de los archivos. Las aplicaciones mantienen sus propios archivos de directorio; cada carga está limitada a 1 MiB.",
      "Connecting storage does not grant apps access. You choose that separately.": "Conectar almacenamiento no concede acceso a las aplicaciones. Tú lo decides por separado.",
      "Google Drive is not configured on this service yet.": "Google Drive aún no está configurado en este servicio.",
      "Google Drive connected. Apps can use files they create in this dedicated folder.": "Google Drive conectado. Las aplicaciones pueden usar los archivos que creen en esta carpeta dedicada.",
      "Google authorization was cancelled. Your other connections are unchanged.": "La autorización de Google se canceló. Tus otras conexiones no han cambiado.",
      "Google Drive could not be connected. Return to Resources and authorize a new connection.": "No se pudo conectar Google Drive. Vuelve a Recursos y autoriza una conexión nueva.",
      "This Google authorization return is incomplete. Connect Google Drive again.": "Este retorno de autorización de Google está incompleto. Conecta Google Drive de nuevo.",
      "Google authorization could not be opened. Please try again.": "No se pudo abrir la autorización de Google. Inténtalo de nuevo.",
      "Choose a connection name.": "Elige un nombre para la conexión.",
      "Sign in to finish Google Drive authorization. If this browser session changed, start a new connection from Resources.": "Inicia sesión para completar la autorización de Google Drive. Si cambió esta sesión del navegador, inicia una conexión nueva desde Recursos.",
