      "Your identity": "Tu identidad",
      "Handle": "Nombre de usuario",
      "Account status": "Estado de la cuenta",
      "Keep your recovery file private and backed up. Losing both your sign-in credentials and recovery file can permanently lock you out.": "Mantén tu archivo de recuperación privado y respaldado. Perder tanto las credenciales como el archivo puede impedir el acceso definitivamente.",
      "You need a new recovery file.": "Necesitas un nuevo archivo de recuperación.",
      "You stopped a disputed move with your recovery file, so that file no longer works. Create a new one now.": "Detuviste una mudanza disputada con tu archivo de recuperación, así que ese archivo ya no funciona. Crea uno nuevo ahora.",
      "Your identity moved here. Create a recovery file in this provider's format.": "Tu identidad se mudó aquí. Crea un archivo de recuperación en el formato de este proveedor.",
      "Your current recovery file was created {date}.": "Tu archivo de recuperación actual se creó el {date}.",
      "This account has no current recovery file.": "Esta cuenta no tiene un archivo de recuperación vigente.",
      "It can authorize moving your identity from {date}.": "Podrá autorizar la mudanza de tu identidad a partir del {date}.",
      "Replacing it makes every copy of your current recovery file stop working. Your sign-in, data and connected apps stay the same.": "Reemplazarlo hace que todas las copias de tu archivo de recuperación actual dejen de funcionar. Tu inicio de sesión, tus datos y tus apps conectadas no cambian.",
      "Create a new recovery file": "Crear un nuevo archivo de recuperación",
      "Replace recovery file": "Reemplazar archivo de recuperación",
      "Recovery files cannot be replaced on this service right now.": "Los archivos de recuperación no se pueden reemplazar en este servicio por ahora.",
      "Replace your recovery file?": "¿Reemplazar tu archivo de recuperación?",
      "Your old recovery file stops working": "Tu archivo de recuperación anterior deja de funcionar",
      " as soon as you confirm the new one. Every copy of it becomes useless, wherever it is stored.": " en cuanto confirmes el nuevo. Todas sus copias quedan inservibles, estén donde estén.",
      "A pending move of your identity to another provider will be cancelled.": "Se cancelará cualquier mudanza pendiente de tu identidad a otro proveedor.",
      "The new file can authorize moving your identity only after 7 days.": "El nuevo archivo solo podrá autorizar una mudanza de tu identidad después de 7 días.",
      "Your email and devices will be notified.": "Se notificará a tu correo y a tus dispositivos.",
      "You will confirm with a password or passkey you have had for at least 7 days, choose your questions, then save and test the new file on this device. Until you confirm, your current file keeps working.": "Confirmarás con una contraseña o llave de acceso que tengas desde hace al menos 7 días, elegirás tus preguntas y luego guardarás y probarás el nuevo archivo en este dispositivo. Hasta que confirmes, tu archivo actual sigue funcionando.",
      "I understand I need to save this new file somewhere safe.": "Entiendo que debo guardar este nuevo archivo en un lugar seguro.",
      "I understand my old recovery file will stop working.": "Entiendo que mi archivo de recuperación anterior dejará de funcionar.",
      "Cancel. Keep my current file": "Cancelar. Conservar mi archivo actual",
      "Confirming this replacement will cancel your pending identity move.": "Confirmar este reemplazo cancelará la mudanza pendiente de tu identidad.",
      "Save your new recovery file.": "Guarda tu nuevo archivo de recuperación.",
      "Download new recovery file": "Descargar nuevo archivo de recuperación",
      "Next: enter every answer again to test the file before it replaces your old one.": "Después: escribe de nuevo cada respuesta para probar el archivo antes de que reemplace al anterior.",
      "Test your new recovery file.": "Prueba tu nuevo archivo de recuperación.",
      "Download new recovery file again": "Descargar de nuevo el archivo de recuperación",
      "Replace your old recovery file.": "Reemplaza tu archivo de recuperación anterior.",
      "Your old recovery file stops working now.": "Tu archivo de recuperación anterior deja de funcionar ahora.",
      // Recovery reissue cooling-off window (wargame 2026-10-23 #1).
      "To cancel, use a device that was signed in before the replacement started or the link in the email notice.": "Para cancelarlo, usa un dispositivo que tuviera la sesión iniciada antes del reemplazo o el enlace del aviso por correo.",
      "This file was replaced recently.": "Este archivo se reemplazó hace poco.",
      "For 7 days after a replacement, the previous file can only cancel it. If you did not replace it, cancel the replacement now; this file then works again.": "Durante 7 días después de un reemplazo, el archivo anterior solo puede cancelarlo. Si no lo reemplazaste tú, cancela el reemplazo ahora; después este archivo vuelve a funcionar.",
      "Cancel the replacement with this file": "Cancelar el reemplazo con este archivo",
      "The replacement was cancelled and this recovery file works again. Unlock it again to recover your account.": "Se canceló el reemplazo y este archivo de recuperación vuelve a funcionar. Desbloquéalo de nuevo para recuperar tu cuenta.",
      "Your recovery file was replaced recently.": "Tu archivo de recuperación se reemplazó hace poco.",
      "The new file can recover your account from {date}. Until then your previous file can only cancel the replacement.": "El archivo nuevo podrá recuperar tu cuenta a partir del {date}. Hasta entonces, tu archivo anterior solo puede cancelar el reemplazo.",
      "Not you? Cancel the replacement from this device.": "¿No fuiste tú? Cancela el reemplazo desde este dispositivo.",
      "To cancel, use a device that was signed in before the replacement started, the link in the email notice, or your previous recovery file.": "Para cancelarlo, usa un dispositivo que tuviera la sesión iniciada antes del reemplazo, el enlace del aviso por correo o tu archivo de recuperación anterior.",
      "Cancel the replacement": "Cancelar el reemplazo",
      "For 7 days after you confirm, the new file cannot recover your account, and your old file can only cancel the replacement. This protects you if someone else started it.": "Durante 7 días después de confirmar, el archivo nuevo no puede recuperar tu cuenta y tu archivo anterior solo puede cancelar el reemplazo. Así estás protegido si lo inició otra persona.",
      "If your account has a passkey, confirm with the passkey; a password is not enough.": "Si tu cuenta tiene una llave de acceso, confirma con ella; una contraseña no basta.",
      "Replacement cancelled. Your previous recovery file works again and the new one never will.": "Reemplazo cancelado. Tu archivo de recuperación anterior vuelve a funcionar y el nuevo no funcionará nunca.",
      "Replacement cancelled. Your previous recovery file works again and the new one never will. This device made the replacement, so it was signed out. Sign in again.": "Reemplazo cancelado. Tu archivo de recuperación anterior vuelve a funcionar y el nuevo no funcionará nunca. Este dispositivo hizo el reemplazo, así que se cerró su sesión. Vuelve a iniciar sesión.",
      "For the next 7 days the new file cannot recover your account, and your old file can only cancel this replacement.": "Durante los próximos 7 días el archivo nuevo no puede recuperar tu cuenta y tu archivo anterior solo puede cancelar este reemplazo.",
      "After this step only the file you just saved can recover your account.": "Después de este paso, solo el archivo que acabas de guardar podrá recuperar tu cuenta.",
      "Your pending identity move will be cancelled.": "Se cancelará la mudanza pendiente de tu identidad.",
      "I saved my new recovery file in a safe place.": "Guardé mi nuevo archivo de recuperación en un lugar seguro.",
      "Replace my recovery file": "Reemplazar mi archivo de recuperación",
