      "Create, save and test a new recovery file on this device.": "Crea, guarda y prueba un nuevo archivo de recuperación en este dispositivo.",
      "Replacement cancelled. Nothing changed.": "Reemplazo cancelado. No cambió nada.",
      "Your new recovery file is active. Reload to see the latest details.": "Tu nuevo archivo de recuperación está activo. Recarga para ver los detalles más recientes.",
      "Confirm that your current recovery file will stop working.": "Confirma que tu archivo de recuperación actual dejará de funcionar.",
