      "Sign out of boot": "Cerrar sesión de boot",
      "Signs boot out everywhere. Only a new token and redeploy restores it.": "Cierra la sesión de boot en todas partes. Solo un nuevo token y un nuevo despliegue lo restauran.",
      "Single-use links that create reserved internal accounts through the normal onboarding flow.": "Enlaces de un solo uso que crean cuentas internas reservadas mediante el flujo normal de incorporación.",
      "Something changed while you were working. The latest state has been reloaded; review it and try again.": "Algo cambió mientras trabajabas. Se recargó el estado más reciente; revísalo e inténtalo de nuevo.",
      "State": "Estado",
      "Status": "Estado",
      "Suspend account": "Suspender cuenta",
      "Suspend account…": "Suspender cuenta…",
      "Suspend this account?": "¿Suspender esta cuenta?",
      "Tamper-evident, not tamper-proof: someone with storage access who rewrites every later entry is not detected. External anchoring of the head is not yet available.": "Revela manipulaciones, pero no las impide: no se detecta a alguien con acceso al almacenamiento que reescriba todas las entradas posteriores. El anclaje externo de la cabecera aún no está disponible.",
      "That confirmation did not succeed. Try again.": "Esa confirmación no funcionó. Inténtalo de nuevo.",
      "The 10-minute setup window closed and the token is now used. Mint a new token and redeploy its digest.": "El plazo de configuración de 10 minutos terminó y el token ya está usado. Emite un nuevo token y despliega su resumen.",
      "The account can sign in again. Only an administrator suspension is lifted; other account states are unchanged.": "La cuenta puede volver a iniciar sesión. Solo se levanta la suspensión de un administrador; los demás estados no cambian.",
      "The account is not in a state that allows this change.": "La cuenta no está en un estado que permita este cambio.",
      "The boot handle is permanently reserved.": "El identificador boot está reservado de forma permanente.",
      "The chain breaks at entry {seq}. Audit storage may have been altered outside the console. Preserve it and investigate.": "La cadena se rompe en la entrada {seq}. Es posible que el almacenamiento de auditoría se haya alterado fuera de la consola. Consérvalo e investiga.",
      "The handle becomes available to anyone again. Assigned handles and handles with outstanding claims are never released.": "El identificador vuelve a estar disponible para cualquiera. Los identificadores asignados o con reclamaciones pendientes nunca se liberan.",
      "The link could not be copied. Select it and copy it manually.": "No se pudo copiar el enlace. Selecciónalo y cópialo a mano.",
      "The link stops working immediately. This cannot be undone; mint a new claim if the person still needs one.": "El enlace deja de funcionar de inmediato. No se puede deshacer; emite una nueva reclamación si la persona aún la necesita.",
      "The passkey request was cancelled or timed out.": "La solicitud de llave de acceso se canceló o caducó.",
      "The request could not be completed ({code}).": "No se pudo completar la solicitud ({code}).",
      "The request was not accepted. Check the fields and try again.": "No se aceptó la solicitud. Revisa los campos e inténtalo de nuevo.",
      "The role catalog is invalid. Check identifiers, names and capability classes.": "El catálogo de roles no es válido. Revisa identificadores, nombres y clases de capacidades.",
      "The service could not be reached. Check your connection and try again.": "No se pudo contactar con el servicio. Revisa tu conexión e inténtalo de nuevo.",
      "The service returned an unexpected response.": "El servicio devolvió una respuesta inesperada.",
      "The two passwords do not match.": "Las dos contraseñas no coinciden.",
      "There is no recovery file for boot.": "Boot no tiene archivo de recuperación.",
      "These are a permanent floor. Change them in HOST_NAME_POLICY, not here. Only boot can mint claims for them.": "Son un mínimo permanente. Cámbialos en HOST_NAME_POLICY, no aquí. Solo boot puede emitir reclamaciones para ellos.",
      "This account loses administrator authority immediately.": "Esta cuenta pierde la autoridad de administrador de inmediato.",
      "This account will be able to reserve handles, mint claims, edit user-class roles and manage ordinary accounts.": "Esta cuenta podrá reservar identificadores, emitir reclamaciones, editar roles de clase usuario y gestionar cuentas ordinarias.",
      "This authenticator already holds a passkey for this site. Use another authenticator.": "Este autenticador ya tiene una llave de acceso para este sitio. Usa otro autenticador.",
      "This badge is limited to reserved internal accounts.": "Esta insignia está limitada a cuentas internas reservadas.",
      "This boot token is invalid, expired or already used.": "Este token de boot no es válido, caducó o ya se usó.",
      "This boot token was already used or its setup window closed. Mint a new token and redeploy its digest.": "Este token de boot ya se usó o su plazo de configuración terminó. Emite un nuevo token y despliega su resumen.",
      "This browser does not support passkeys.": "Este navegador no admite llaves de acceso.",
      "This claim token is no longer usable.": "Este token de reclamación ya no se puede usar.",
      "This deployment has no boot token digest, so boot cannot be claimed or restored here.": "Este despliegue no tiene resumen de token de boot, así que boot no se puede reclamar ni restaurar aquí.",
      "This does not look like a boot token. It starts with “boot1.”.": "Esto no parece un token de boot. Empieza por «boot1.».",
      "This handle already has a permanent assignment.": "Este identificador ya tiene una asignación permanente.",
      "This handle has an outstanding claim token. Revoke it first.": "Este identificador tiene un token de reclamación pendiente. Revócalo primero.",
      "This is not a boot token file.": "Esto no es un archivo de token de boot.",
      "This link is a bearer capability: anyone who opens it can claim this handle with the roles and badges above. Send it only to the intended person over a trusted channel.": "Este enlace es una capacidad al portador: cualquiera que lo abra puede reclamar este identificador con los roles e insignias indicados. Envíalo solo a la persona destinataria por un canal de confianza.",
      "This request did not come from this console’s exact origin. Reload the page and try again.": "Esta solicitud no procede del origen exacto de esta consola. Recarga la página e inténtalo de nuevo.",
      "This token is older than its 30-minute window. Mint a new token and redeploy its digest.": "Este token supera su plazo de 30 minutos. Emite un nuevo token y despliega su resumen.",
      "This token was minted for another origin. Mint one for this console’s exact origin.": "Este token se emitió para otro origen. Emite uno para el origen exacto de esta consola.",
      "Tick the acknowledgement to confirm you understand when boot access ends.": "Marca la confirmación para indicar que entiendes cuándo termina el acceso de boot.",
      "To configure boot": "Para configurar boot",
