      "Client hosts": "Hosts de clientes",
      "Apps may sign in with a URL client ID that this host resolves from the app’s own metadata document. Block a host to refuse all such apps on it.": "Las aplicaciones pueden iniciar sesión con un ID de cliente en forma de URL que este host resuelve desde el documento de metadatos de la propia aplicación. Bloquea un host para rechazar todas esas aplicaciones en él.",
      "Block a host": "Bloquear un host",
