      "Value": "Valor",
      "Verified email": "Correo verificado",
      "Verify entire chain": "Verificar toda la cadena",
      "Whoever opens this link can create an account with full administrator authority. Only send it to the intended person over a trusted channel.": "Quien abra este enlace podrá crear una cuenta con autoridad completa de administrador. Envíalo solo a la persona destinataria por un canal de confianza.",
      "Within 30 minutes of minting, open /console?boot and paste or import the token file.": "En los 30 minutos siguientes a la emisión, abre /console?boot y pega o importa el archivo del token.",
      "You are boot: you can classify capabilities, roles and badges and mark internal roles delegable. Boot-only controls are outlined in amber.": "Eres boot: puedes clasificar capacidades, roles e insignias y marcar roles internos como delegables. Los controles exclusivos de boot tienen borde ámbar.",
      "You can add, edit and delete user-class roles from capabilities boot has declared safe for anyone. Controls outlined in amber are boot-only and stay disabled for administrators.": "Puedes añadir, editar y eliminar roles de clase usuario con capacidades que boot declaró seguras para cualquiera. Los controles con borde ámbar son exclusivos de boot y siguen desactivados para administradores.",
      "You ended boot access. Boot can no longer sign in or act. Administrators, roles and claims are unaffected.": "Terminaste el acceso de boot. Boot ya no puede iniciar sesión ni actuar. Los administradores, roles y reclamaciones no se ven afectados.",
      "You signed out of boot.": "Cerraste la sesión de boot.",
